begin;
with checked_provider_input as (
select * from jsonb_to_recordset('[{"id": "2fd05112-ed75-4e3c-9133-3a9a1dcc517a", "name": "Mr. Handyman Serving Livermore - Pleasanton", "city": "Livermore", "address": "4047 1st Street #207, Livermore, CA 94551", "phone": "(925) 326-9079", "website": "https://www.mrhandyman.com/livermore-pleasanton/", "description": "Home repair, assembly, carpentry and painting. Based in Livermore; the official service-area pages list Mountain House and Tracy. Confirm the exact job with the provider.", "tags": ["handyman", "small repairs", "painting", "assembly"], "source": "https://www.mrhandyman.com/livermore-pleasanton/", "additional_sources": ["https://www.mrhandyman.com/livermore-pleasanton/geo/tracy/", "https://www.mrhandyman.com/livermore-pleasanton/geo/mountain-house/"]}, {"id": "aea50b94-f9d9-4faa-b08b-89bd46ed66dc", "name": "Molly Maid of Stockton, Elk Grove, Tracy, and Modesto", "city": "Lathrop", "address": "125 D''Arcy Parkway, Lathrop, CA 95330", "phone": "(209) 788-8027", "website": "https://www.mollymaid.com/locations/california/mountain-house/", "description": "Recurring, one-time and moving-related house cleaning. Based in Lathrop; the official location pages identify Mountain House and Tracy service. Confirm your address and cleaning needs directly.", "tags": ["house cleaning", "recurring cleaning", "move-out cleaning"], "source": "https://www.mollymaid.com/locations/california/mountain-house/", "additional_sources": []}, {"id": "1f306383-3cd8-4b85-8e1b-7417df93ecac", "name": "Roto-Rooter Tracy", "city": "Tracy", "address": "", "phone": "(209) 362-1914", "website": "https://www.rotorooter.com/tracyca/", "description": "Plumbing, drain cleaning, leak detection and water-heater services for Tracy and the Mountain House corridor, as stated on the official local service page. Confirm response time and pricing directly.", "tags": ["plumbing", "drain cleaning", "water heaters"], "source": "https://www.rotorooter.com/tracyca/", "additional_sources": []}]'::jsonb) x(id uuid,name text,city text,address text,phone text,website text,description text,tags jsonb,source text)
), logged as (
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)
select b.id,jsonb_build_object('name',b.name,'city',b.city,'address',b.address,'phone',b.phone,'website',b.website,'description',b.description,'rating',b.rating,'review_count',b.review_count,'verified_at',b.verified_at,'verification_source',b.verification_source),
jsonb_build_object('name',i.name,'city',i.city,'address',i.address,'phone',i.phone,'website',i.website,'description',i.description,'rating',null,'review_count',0,'verification_source','first_party_website_desk_check'),
'Corrected identity, public contact, location and service area against official provider website; cleared unsupported legacy rating',i.source
from public.businesses b join checked_provider_input i on i.id=b.id returning business_id
), changed as (
update public.businesses b set name=i.name,city=i.city,address=i.address,phone=i.phone,website=i.website,description=i.description,rating=null,review_count=0,
verified_at=now(),verification_source='first_party_website_desk_check'
from checked_provider_input i join logged l on l.business_id=i.id where b.id=i.id returning b.id
)
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)
select id,source,array['identity','public phone','website','location','advertised services','advertised service area'],array['Mountain House','Tracy'],array(select jsonb_array_elements_text(tags)),
'Official website desk check only. Public details and advertised service areas were compared; no phone call, owner confirmation, license verification, insurance check, availability check or quality endorsement.' from checked_provider_input where id in (select id from changed)
on conflict(business_id) do update set checked_at=now(),source_url=excluded.source_url,checked_fields=excluded.checked_fields,service_areas=excluded.service_areas,service_tags=excluded.service_tags,scope_note=excluded.scope_note;
commit;
select count(*) as checked_existing_providers from public.listing_checks;
